using Servicio.RetazoMarket.Business.DTOs.Material;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class MaterialService:IMaterialService { private readonly IMaterialDataService _data;private readonly ICategoriaMaterialDataService _categorias;public MaterialService(IMaterialDataService data,ICategoriaMaterialDataService categorias)=>(_data,_categorias)=(data,categorias);public async Task<IReadOnlyList<MaterialResponse>> ObtenerTodosAsync(CancellationToken ct=default)=>(await _data.ObtenerTodosAsync(ct)).Select(MaterialBusinessMapper.ToResponse).ToList();public async Task<MaterialResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _data.ObtenerPorIdAsync(id,ct);return m is null?null:MaterialBusinessMapper.ToResponse(m);}public async Task<MaterialResponse?> ObtenerPorNombreAsync(string n,CancellationToken ct=default){var m=await _data.ObtenerPorNombreAsync(n.Trim(),ct);return m is null?null:MaterialBusinessMapper.ToResponse(m);}public async Task<DataPagedResult<MaterialResponse>> BuscarAsync(MaterialFiltroRequest f,CancellationToken ct=default){var e=MaterialValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _data.BuscarAsync(new MaterialFiltroDataModel{nombre=f.nombre?.Trim(),id_categoria=f.id_categoria,estado=f.estado?.Trim().ToUpperInvariant(),stockMinimo=f.stock_minimo,stockMaximo=f.stock_maximo,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(MaterialBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<MaterialResponse> CrearAsync(CrearMaterialRequest r,CancellationToken ct=default){var e=MaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await CategoriaActiva(r.id_categoria,ct);if(await _data.ExistePorNombreAsync(r.mat_nombre.Trim(),ct))throw new ValidationException("Ya existe un material con ese nombre.");return MaterialBusinessMapper.ToResponse(await _data.CrearAsync(MaterialBusinessMapper.ToDataModel(r),ct));}public async Task<MaterialResponse?> ActualizarAsync(ActualizarMaterialRequest r,CancellationToken ct=default){var e=MaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var actual=await _data.ObtenerPorIdAsync(r.id_material,ct);if(actual is null)return null;await CategoriaActiva(r.id_categoria,ct);var otro=await _data.ObtenerPorNombreAsync(r.mat_nombre.Trim(),ct);if(otro is not null&&otro.id_material!=r.id_material)throw new ValidationException("Ya existe otro material con ese nombre.");var m=await _data.ActualizarAsync(MaterialBusinessMapper.ToDataModel(r,actual.stock_actual),ct);return m is null?null:MaterialBusinessMapper.ToResponse(m);}public Task<bool> EliminarAsync(int id,CancellationToken ct=default)=>_data.EliminarLogicoAsync(id,ct);private async Task CategoriaActiva(int id,CancellationToken ct){var c=await _categorias.ObtenerPorIdAsync(id,ct);if(c is null||c.cat_estado!="ACT")throw new ValidationException("La categoría no existe o está inactiva.");}}
